import numpy as np
def dsigmoid(z):
    s = 1 / (1 + np.exp(-z))
    return s * (1 - s)
# the sigmoid gradient is tiny far from 0 -> vanishing gradients
print(round(float(dsigmoid(0)), 4), round(float(dsigmoid(10)), 6))

