import numpy as np
def dsigmoid(z):
    s = 1 / (1 + np.exp(-z))
    return s * (1 - s)
# el gradiente de la sigmoide es minusculo lejos de 0 -> gradientes que se desvanecen
print(round(float(dsigmoid(0)), 4), round(float(dsigmoid(10)), 6))
